// Scaffolding: tool schemas + non-exercise tool implementations (write_file, message_user, ask_user, read_board, update_board). Exercise tools live in exercises.rs. Attendees do not edit this file.

use std::{
    fmt, fs,
    path::{Path, PathBuf},
};

use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use serde_json::Value;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub(crate) enum ToolName {
    ReadFile,
    WriteFile,
    EditFile,
    Shell,
    ListFiles,
    WebFetch,
    MessageUser,
    AskUser,
    ReadBoard,
    UpdateBoard,
}

#[derive(Debug, Deserialize, Serialize, JsonSchema)]
pub(crate) struct ListFilesParams {
    #[schemars(description = "Directory path to list")]
    pub(crate) path: String,
    #[schemars(description = "Maximum depth to recurse (1 = immediate children only)")]
    pub(crate) max_depth: usize,
}

impl ToolName {
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            Self::ReadFile => "read_file",
            Self::WriteFile => "write_file",
            Self::EditFile => "edit_file",
            Self::Shell => "shell",
            Self::ListFiles => "list_files",
            Self::WebFetch => "web_fetch",
            Self::MessageUser => "message_user",
            Self::AskUser => "ask_user",
            Self::ReadBoard => "read_board",
            Self::UpdateBoard => "update_board",
        }
    }

    pub(crate) fn from_str(s: &str) -> Option<Self> {
        match s {
            "read_file" => Some(Self::ReadFile),
            "write_file" => Some(Self::WriteFile),
            "edit_file" => Some(Self::EditFile),
            "shell" => Some(Self::Shell),
            "list_files" => Some(Self::ListFiles),
            "web_fetch" => Some(Self::WebFetch),
            "message_user" => Some(Self::MessageUser),
            "ask_user" => Some(Self::AskUser),
            "read_board" => Some(Self::ReadBoard),
            "update_board" => Some(Self::UpdateBoard),
            _ => None,
        }
    }
}

impl fmt::Display for ToolName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl PartialEq<&str> for ToolName {
    fn eq(&self, other: &&str) -> bool {
        self.as_str() == *other
    }
}

impl PartialEq<str> for ToolName {
    fn eq(&self, other: &str) -> bool {
        self.as_str() == other
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ToolResult {
    Ok(String),
    Err(String),
}

impl ToolResult {
    pub(crate) fn is_error(&self) -> bool {
        matches!(self, Self::Err(_))
    }

    pub(crate) fn text(&self) -> &str {
        match self {
            Self::Ok(s) | Self::Err(s) => s,
        }
    }
}

impl PartialEq<&str> for ToolResult {
    fn eq(&self, other: &&str) -> bool {
        match self {
            Self::Ok(text) => text == *other,
            Self::Err(text) => {
                if let Some(stripped) = other.strip_prefix("Error: ") {
                    text == stripped
                } else {
                    text == *other
                }
            }
        }
    }
}

impl fmt::Display for ToolResult {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.text())
    }
}

