/// Update one phase on a generic kanban board.
#[derive(Debug, Deserialize, Serialize, JsonSchema)]
pub(crate) struct UpdateBoardParams {
    pub(crate) path: String,
    pub(crate) phase: String,
    pub(crate) status: String,
    pub(crate) artifact: Option<String>,
}

pub(crate) fn execute_write_file(args: Value) -> ToolResult {
    let params: WriteFileParams = match serde_json::from_value(args) {
        Ok(v) => v,
        Err(e) => return ToolResult::Err(format!("writing file: invalid arguments: {e}")),
    };

    match fs::write(&params.path, params.content) {
        Ok(_) => ToolResult::Ok(format!("Successfully wrote to {}", params.path)),
        Err(e) => ToolResult::Err(format!("writing file: {e}")),
    }
}

pub(crate) fn execute_message_user(args: Value) -> ToolResult {
    match serde_json::from_value::<MessageUserParams>(args) {
        Ok(p) => ToolResult::Ok(p.message),
        Err(e) => ToolResult::Err(format!("invalid arguments: {e}")),
    }
}

pub(crate) fn execute_ask_user(args: Value) -> ToolResult {
    match serde_json::from_value::<AskUserParams>(args) {
        Ok(p) => ToolResult::Ok(p.question),
        Err(e) => ToolResult::Err(format!("invalid arguments: {e}")),
    }
}

pub(crate) fn execute_read_board(args: Value) -> ToolResult {
    let params: ReadBoardParams = match serde_json::from_value(args) {
        Ok(v) => v,
        Err(e) => return ToolResult::Err(format!("invalid arguments: {e}")),
    };

    let board_path = Path::new(&params.path);
    if !board_path.exists() {
        return ToolResult::Err(format!("board not found: {}", params.path));
    }

    match fs::read_to_string(board_path) {
        Ok(content) => match serde_json::from_str::<Value>(&content) {
            Ok(_) => ToolResult::Ok(content),
            Err(e) => ToolResult::Err(format!("reading board: {e}")),
        },
        Err(e) => ToolResult::Err(format!("reading board: {e}")),
    }
}

pub(crate) fn execute_update_board(args: Value) -> ToolResult {
    let params: UpdateBoardParams = match serde_json::from_value(args) {
        Ok(v) => v,
        Err(e) => return ToolResult::Err(format!("invalid arguments: {e}")),
    };

    let board_path = Path::new(&params.path);
    if !board_path.exists() {
        return ToolResult::Err(format!("board not found: {}", params.path));
    }

    let board_content = match fs::read_to_string(board_path) {
        Ok(content) => content,
        Err(e) => return ToolResult::Err(format!("updating board: {e}")),
    };
    let mut board: Value = match serde_json::from_str(&board_content) {
        Ok(value) => value,
        Err(e) => return ToolResult::Err(format!("updating board: {e}")),
    };

    let Some(phases) = board.get_mut("phases").and_then(Value::as_object_mut) else {
        return ToolResult::Err(format!("unknown phase: {}", params.phase));
    };
    let Some(phase_obj) = phases.get_mut(&params.phase).and_then(Value::as_object_mut) else {
        return ToolResult::Err(format!("unknown phase: {}", params.phase));
    };

    phase_obj.insert("status".to_string(), Value::String(params.status.clone()));
    if let Some(artifact) = params.artifact {
        phase_obj.insert("artifact".to_string(), Value::String(artifact));
    }
    board["currentPhase"] = Value::String(params.phase);

    let board_pretty = match serde_json::to_string_pretty(&board) {
        Ok(text) => text,
        Err(e) => return ToolResult::Err(format!("updating board: {e}")),
    };

    if let Err(e) = fs::write(board_path, format!("{}\n", board_pretty)) {
        return ToolResult::Err(format!("updating board: {e}"));
    }

    ToolResult::Ok(board_pretty)
}

pub(crate) fn format_tool_for_context(tool: &Tool) -> String {
    let schema_json =
        serde_json::to_string_pretty(&tool.schema).unwrap_or_else(|_| "{}".to_string());
    format!(
        "### {}\n{}\nParameters:\n```json\n{}\n```",
        tool.name, tool.description, schema_json
    )
}

pub(crate) fn get_enabled_tools(
    config: &crate::config::AgentConfig,
    all_tools: &[Tool],
) -> Vec<Tool> {
    match &config.tools {
        ToolSelection::All => all_tools.to_vec(),
        ToolSelection::Only(enabled_tools) => all_tools
            .iter()
            .filter(|tool| tool.name == ToolName::MessageUser || enabled_tools.contains(&tool.name))
            .cloned()
            .collect(),
    }
}
